INSERT INTO "expansion_scenarios" ("id","scenario_code","version","name_en","name_zh","description_en","description_zh","forecast_horizon_months","status","advisory_disclaimer_en","advisory_disclaimer_zh","created_by_user_id","approved_by_user_id","approved_at","created_at","updated_at") VALUES ('exs-x02-v2','ADC-X02',2,'Capital-efficient corridor','资本效率走廊方案','Two compact clinics prioritising early payback and proven catchments.','新设两家紧凑型诊所，优先考虑较短回收期和成熟客群。',24,'APPROVED','Advisory forecast; management approval and site due diligence remain mandatory.','本结果仅供决策参考；仍需管理层批准及选址尽调。','usr-local-ops','usr-local-ops','2026-09-18 16:30:00','2026-09-23 12:00:00','2026-09-23 12:00:00'),
('exs-x03-v1','ADC-X03',1,'Specialist hub strategy','专科中心方案','Two larger specialist hubs with higher capital and referral capacity.','新设两家较大型专科中心，提高转诊承接能力。',36,'REVIEW','Advisory forecast; qualification recruitment assumptions are not commitments.','本结果仅供决策参考；资质人员招募假设不构成承诺。','usr-local-ops',NULL,NULL,'2026-09-23 12:00:00','2026-09-23 12:00:00'),
('exs-x04-v3','ADC-X04',3,'Balanced Greater Bay expansion','大湾区均衡扩张方案','Three clinics balancing demand, capital, qualification coverage and travel constraints.','新设三家诊所，综合平衡需求、资本、资质覆盖与跨店出行约束。',24,'RECOMMENDED','Advisory forecast; no scenario automatically changes live operations.','本结果仅供决策参考；任何方案都不会自动更改实际运营。','usr-local-ops','usr-local-ops','2026-09-22 18:10:00','2026-09-23 12:00:00','2026-09-23 12:00:00') ON CONFLICT DO NOTHING;
